            ]
        },
        ["PKG-2002"] = new Shipment
        {
            TrackingNumber = "PKG-2002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 3, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 5, 28, 10, 0, 0, TimeSpan.Zero), Status = "Order Placed", Location = "Seattle, WA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 5, 29, 7, 45, 0, TimeSpan.Zero), Status = "Picked Up", Location = "Seattle, WA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 5, 31, 16, 20, 0, TimeSpan.Zero), Status = "In Transit", Location = "Portland, OR" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 2, 11, 0, 0, TimeSpan.Zero), Status = "Out for Delivery", Location = "San Francisco, CA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 2, 14, 35, 0, TimeSpan.Zero), Status = "Delivered", Location = "San Francisco, CA" },
            ]
        },
        ["PKG-3003"] = new Shipment
        {
            TrackingNumber = "PKG-3003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 10, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 4, 1, 0, 0, TimeSpan.Zero), Status = "Order Placed", Location = "Dallas, TX" },
            ]
        },
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

